"""A headless terminal backed by a real pty plus a VT100 screen emulator.

The terminal runs an *interactive* bash shell (so startup files such as
``~/.bashrc`` are sourced) attached to a pseudo terminal.  Everything the shell
(and any program running inside it) writes is fed to a ``pyte`` screen, so
full-screen / interactive programs (vim, top, less, the python REPL, ...)
render exactly like they would in a real terminal.

Example::

    from headless_terminal import HeadlessTerminal

    term = HeadlessTerminal()
    term.send_keystrokes("echo hello\\n", wait_sec=1)
    print(term.get_screen())
    term.send_keystrokes("\\x03")  # Ctrl-C
    term.close()
"""

from __future__ import annotations

import errno
import fcntl
import os
import pty
import re
import select
import shutil
import signal
import struct
import termios
import threading
import time
from typing import List, Optional, Sequence, Union

try:
    from base_terminal import BaseTerminal
except ImportError:  # pragma: no cover - allow import from another cwd
    import sys as _sys

    _sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    from base_terminal import BaseTerminal

try:
    import pyte
except ImportError as exc:  # pragma: no cover
    raise ImportError(
        "headless_terminal requires the 'pyte' package (pip install pyte)"
    ) from exc


_ANSI_RE = re.compile(
    rb"\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)"      # OSC
    rb"|\x1b\[[0-?]*[ -/]*[@-~]"               # CSI
    rb"|\x1b[PX^_][^\x1b]*(?:\x1b\\)?"         # DCS/PM/APC/SOS
    rb"|\x1b[@-Z\\-_]"                         # 2-byte escapes
    rb"|[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]"      # other control chars
)


def _make_screen(columns: int, lines: int):
    """Create the most capable screen the installed pyte version offers."""
    history_screen = getattr(pyte, "HistoryScreen", None)
    if history_screen is not None:
        for kwargs in ({"history": 10000, "ratio": 0.5}, {}):
            try:
                return history_screen(columns, lines, **kwargs)
            except Exception:
                continue
    return pyte.Screen(columns, lines)


def _make_stream(screen):
    """Return a byte-oriented stream feeding ``screen`` (version tolerant)."""
    byte_stream = getattr(pyte, "ByteStream", None)
    if byte_stream is not None:
        try:
            return byte_stream(screen), True
        except Exception:
            pass
    return pyte.Stream(screen), False


class HeadlessTerminal(BaseTerminal):
    """A headless, scriptable terminal running an interactive shell."""

    def __init__(
        self,
        command: Optional[Union[str, Sequence[str]]] = None,
        rows: int = 48,
        cols: int = 160,
        cwd: Optional[str] = None,
        env: Optional[dict] = None,
        startup_wait_sec: float = 1.0,
        **kwargs,
    ) -> None:
        # Accept common aliases so callers can use whichever spelling.
        rows = int(kwargs.pop("height", kwargs.pop("lines", rows)))
        cols = int(kwargs.pop("width", kwargs.pop("columns", cols)))
        if command is None:
            command = kwargs.pop("cmd", None) or kwargs.pop("shell", None)
        kwargs.pop("no_rebuild", None)  # ignore unknown extras rather than fail

        self.rows = max(1, rows)
        self.cols = max(1, cols)

        if command is None:
            bash = shutil.which("bash") or "/bin/bash"
            # -i => interactive shell => ~/.bashrc (and /etc/bash.bashrc) sourced.
            argv: List[str] = [bash, "-i"]
        elif isinstance(command, str):
            argv = [command]
        else:
            argv = list(command)
        self.command = argv

        child_env = dict(os.environ if env is None else env)
        child_env.setdefault("TERM", "xterm-256color")
        child_env.setdefault("LANG", child_env.get("LC_ALL", "C.UTF-8"))
        child_env["COLUMNS"] = str(self.cols)
        child_env["LINES"] = str(self.rows)
        # Make sure bash does not skip rc files because it thinks it is not
        # interactive, and keep history/pager behaviour predictable.
        child_env.setdefault("PS1", child_env.get("PS1", "$ "))

        self._screen = _make_screen(self.cols, self.rows)
        self._stream, self._stream_is_bytes = _make_stream(self._screen)
        self._raw = bytearray()
        self._lock = threading.RLock()
        self._closed = False
        self._last_output_time = time.monotonic()
        self._decoder_buf = b""

        self.pid, self._master_fd = pty.fork()
        if self.pid == 0:  # child
            try:
                os.setsid()
            except OSError:
                pass
            try:
                if cwd:
                    os.chdir(cwd)
                self._set_child_winsize()
                os.execvpe(argv[0], argv, child_env)
            except Exception:
                os._exit(127)

        # parent
        self.set_size(self.rows, self.cols)
        flags = fcntl.fcntl(self._master_fd, fcntl.F_GETFL)
        fcntl.fcntl(self._master_fd, fcntl.F_SETFL, flags | os.O_NONBLOCK)

        self._reader = threading.Thread(target=self._read_loop, daemon=True)
        self._reader.start()

        if startup_wait_sec:
            # Wait for the shell to finish printing its first prompt.
            self._wait_for_idle(idle_sec=0.25, timeout_sec=startup_wait_sec)

    # ------------------------------------------------------------------
    # internals
    # ------------------------------------------------------------------
    def _set_child_winsize(self) -> None:
        try:
            fcntl.ioctl(
                0,
                termios.TIOCSWINSZ,
                struct.pack("HHHH", self.rows, self.cols, 0, 0),
            )
        except Exception:
            pass

    def _read_loop(self) -> None:
        while True:
            try:
                r, _, _ = select.select([self._master_fd], [], [], 0.05)
            except (OSError, ValueError):
                break
            if not r:
                if self._closed:
                    break
                continue
            try:
                data = os.read(self._master_fd, 65536)
            except OSError as exc:
                if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK, errno.EINTR):
                    continue
                break
            except ValueError:
                break
            if not data:
                break
            self._feed(data)

    def _feed(self, data: bytes) -> None:
        with self._lock:
            self._raw.extend(data)
            if self._stream_is_bytes:
                self._stream.feed(data)
            else:
                buf = self._decoder_buf + data
                try:
                    text = buf.decode("utf-8")
                    self._decoder_buf = b""
                except UnicodeDecodeError:
                    # keep the incomplete trailing sequence for next time
                    for cut in range(1, min(4, len(buf)) + 1):
                        try:
                            text = buf[:-cut].decode("utf-8")
                            self._decoder_buf = buf[-cut:]
                            break
                        except UnicodeDecodeError:
                            continue
                    else:
                        text = buf.decode("utf-8", "replace")
                        self._decoder_buf = b""
                self._stream.feed(text)
            self._last_output_time = time.monotonic()

    def _wait_for_idle(self, idle_sec: float = 0.2, timeout_sec: float = 5.0) -> None:
        deadline = time.monotonic() + max(0.0, timeout_sec)
        while time.monotonic() < deadline:
            with self._lock:
                quiet = time.monotonic() - self._last_output_time
            if quiet >= idle_sec:
                return
            time.sleep(0.02)

    # ------------------------------------------------------------------
    # BaseTerminal API
    # ------------------------------------------------------------------
    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        """Send ``keystrokes`` to the terminal and wait ``wait_sec`` seconds."""
        if self._closed:
            raise RuntimeError("terminal is closed")
        if isinstance(keystrokes, bytes):
            data = keystrokes
        else:
            data = str(keystrokes).encode("utf-8", "surrogateescape")

        written = 0
        deadline = time.monotonic() + 10.0
        while written < len(data):
            try:
                written += os.write(self._master_fd, data[written:])
            except OSError as exc:
                if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK, errno.EINTR):
                    if time.monotonic() > deadline:
                        raise
                    time.sleep(0.01)
                    continue
                raise

        if wait_sec and wait_sec > 0:
            time.sleep(wait_sec)
        # Let the reader thread render everything already produced.
        self._wait_for_idle(idle_sec=0.05, timeout_sec=0.3)

    # convenient aliases -------------------------------------------------
    send_keys = send_keystrokes
    send = send_keystrokes
    type = send_keystrokes

    def send_command(self, command: str, wait_sec: float = 1.0) -> str:
        """Type ``command``, press Enter, and return the resulting screen."""
        if not command.endswith("\n"):
            command += "\n"
        self.send_keystrokes(command, wait_sec=wait_sec)
        return self.get_screen()

    # ------------------------------------------------------------------
    # screen access
    # ------------------------------------------------------------------
    def get_screen(self, strip: bool = True) -> str:
        """Return the current screen contents as text."""
        with self._lock:
            lines = list(self._screen.display)
        if strip:
            lines = [line.rstrip() for line in lines]
            while lines and not lines[-1]:
                lines.pop()
        return "\n".join(lines)

    # common alternative names used by callers/tests
    def capture_pane(self, *args, **kwargs) -> str:
        return self.get_screen()

    def get_screen_text(self) -> str:
        return self.get_screen()

    def read_screen(self) -> str:
        return self.get_screen()

    def get_display(self) -> str:
        return self.get_screen()

    def screenshot(self) -> str:
        return self.get_screen()

    @property
    def screen(self) -> str:
        return self.get_screen()

    @property
    def display(self) -> List[str]:
        with self._lock:
            return list(self._screen.display)

    def get_cursor(self):
        with self._lock:
            cursor = self._screen.cursor
        return (cursor.y, cursor.x)

    def get_raw_output(self) -> bytes:
        """All bytes emitted by the terminal so far, escape codes included."""
        with self._lock:
            return bytes(self._raw)

    def get_output(self) -> str:
        """All output so far with ANSI escape sequences removed."""
        raw = self.get_raw_output().replace(b"\r\n", b"\n").replace(b"\r", b"\n")
        return _ANSI_RE.sub(b"", raw).decode("utf-8", "replace")

    def clear_screen(self) -> None:
        with self._lock:
            self._screen.reset()

    def wait_for_idle(self, idle_sec: float = 0.3, timeout_sec: float = 30.0) -> None:
        """Block until the terminal produces no output for ``idle_sec``."""
        self._wait_for_idle(idle_sec=idle_sec, timeout_sec=timeout_sec)

    def wait_for_text(
        self, text: str, timeout_sec: float = 10.0, poll_sec: float = 0.05
    ) -> bool:
        """Wait until ``text`` appears on screen; return whether it did."""
        deadline = time.monotonic() + timeout_sec
        while time.monotonic() < deadline:
            if text in self.get_screen():
                return True
            time.sleep(poll_sec)
        return text in self.get_screen()

    # ------------------------------------------------------------------
    # lifecycle
    # ------------------------------------------------------------------
    def set_size(self, rows: int, cols: int) -> None:
        self.rows, self.cols = max(1, int(rows)), max(1, int(cols))
        try:
            fcntl.ioctl(
                self._master_fd,
                termios.TIOCSWINSZ,
                struct.pack("HHHH", self.rows, self.cols, 0, 0),
            )
        except Exception:
            pass
        with self._lock:
            try:
                self._screen.resize(self.rows, self.cols)
            except Exception:
                pass
        try:
            os.kill(self.pid, signal.SIGWINCH)
        except (OSError, ProcessLookupError):
            pass

    def is_alive(self) -> bool:
        try:
            pid, _ = os.waitpid(self.pid, os.WNOHANG)
        except (ChildProcessError, OSError):
            return False
        return pid == 0

    def close(self, timeout_sec: float = 2.0) -> None:
        """Terminate the shell and release the pty."""
        if self._closed:
            return
        self._closed = True
        try:
            os.kill(self.pid, signal.SIGHUP)
        except OSError:
            pass
        deadline = time.monotonic() + timeout_sec
        while time.monotonic() < deadline:
            try:
                pid, _ = os.waitpid(self.pid, os.WNOHANG)
            except (ChildProcessError, OSError):
                break
            if pid != 0:
                break
            time.sleep(0.02)
        else:
            try:
                os.kill(self.pid, signal.SIGKILL)
                os.waitpid(self.pid, 0)
            except (ChildProcessError, OSError):
                pass
        if self._reader.is_alive():
            self._reader.join(timeout=1.0)
        try:
            os.close(self._master_fd)
        except OSError:
            pass

    stop = close
    kill = close
    terminate = close

    def __enter__(self) -> "HeadlessTerminal":
        return self

    def __exit__(self, *exc_info) -> None:
        self.close()

    def __del__(self):  # pragma: no cover - best effort cleanup
        try:
            self.close()
        except Exception:
            pass

    def __str__(self) -> str:
        return self.get_screen()
